export const code = async (inputs) => {
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const str = (v) => String(v === undefined || v === null ? '' : v);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = str(c.value);
    });
    return out;
  };
  const parseIso = (s) => Date.parse(/[Zz]$/.test(s) || /[+-][0-9]{2}:?[0-9]{2}$/.test(s) ? s : s + 'Z');

  const bot = str(inputs.botUsername).trim();
  const nowMs = Date.now();

  // Публичный срез: только опубликованные и завершённые (ADR-0023).
  // Постфильтр повторяет фильтр шага — defense in depth (Q25).
  const visible = (r) => r.status === 'published' || r.status === 'finished';
  const isPast = (r) => {
    const endMs = parseIso(r.ends_at || r.starts_at || '');
    return isFinite(endMs) ? endMs <= nowMs : false;
  };
  const byStart = (a, b) => parseIso(a.starts_at) - parseIso(b.starts_at);
  // register_link собирает сервер из BOT_USERNAME — SPA не запекает имя бота (ADR-0023).
  const item = (r) => ({
    id: r.id || '',
    title: r.title || '',
    address: r.address || '',
    startsAt: r.starts_at || '',
    endsAt: r.ends_at || '',
    status: r.status || '',
    registerLink: bot === '' ? '' : 'https://t.me/' + bot + '?start=e' + (r.id || '')
  });

  const rows = arr(inputs.eventRecords).map(flat).filter(visible);
  const upcoming = rows.filter((r) => !isPast(r)).sort(byStart).map(item);
  const past = rows.filter(isPast).sort(byStart).map(item);

  return { httpStatus: 200, ok: true, upcoming: upcoming, past: past };
};
